    def get_active_descendent(self):
        """
        Get active descendent
        """
        accContext=self.bridge.getActiveDescendent(self.vmid, self.accessible_context)
        if accContext:
            return self.__class__(self.hwnd, self.vmid, accContext)
        else:
            return None

    def get_accessible_context_at(self, x, y):
        """
        Get Accessible Context at position (x, y)
        """
        newAccContext = JOBJECT64()
        res = self.bridge.getAccessibleContextAt(self.vmid, self.accessible_context, x, y, byref(newAccContext)) 
        if not res or not newAccContext:
            return None
        if not self.bridge.isSameObject(self.vmid, newAccContext, self.accessible_context):
            return self.__class__(self.hwnd, self.vmid, newAccContext)
        elif newAccContext!=self.accessible_context:
           self.bridge.releaseJavaObject(self.vmid, newAccContext)
        return None

    def get_current_accessible_value_from_context(self):
        """
        Get current accessible value from context
        """
        buf = create_unicode_buffer(SHORT_STRING_SIZE+1) #(ctypes.c_wchar * (SHORT_STRING_SIZE + 1))() 
        self.bridge.getCurrentAccessibleValueFromContext(self.vmid, self.accessible_context, buf, SHORT_STRING_SIZE)
        return buf.value

